const VERSION = 'raven-v7.4-mech';
const DUR = 7100;
const CSS = "\n:host{\n  color-scheme:dark;\n  --bg:#04060a;\n  --line:rgba(255,255,255,.07);\n  --text:#f5f8ff;\n  --muted:#97a6bc;\n  --accent:#ff2740;\n  --accent2:#9effb1;\n  --card:rgba(8,11,18,.78);\n  --shadow:0 30px 90px rgba(0,0,0,.58);\n  --ease-mech:cubic-bezier(.16,.88,.20,1.02);\n  --ease-mech-soft:cubic-bezier(.19,.74,.16,.99);\n  --ease-turn:cubic-bezier(.54,.02,.20,.98);\n}\n*{box-sizing:border-box}\nhtml,body{margin:0;min-height:100%;background:var(--bg);font-family:Inter,ui-sans-serif,system-ui,-apple-system,\"Segoe UI\",sans-serif;color:var(--text)}\nbody{overflow-x:hidden;background:\n  radial-gradient(circle at 50% 12%, rgba(32,44,86,.48), transparent 34%),\n  radial-gradient(circle at 50% 46%, rgba(255,39,64,.10), transparent 18%),\n  linear-gradient(180deg, #080b12 0%, #05070c 100%);\n}\n.home{min-height:100vh;display:grid;place-items:center;padding:22px}\n.card{width:min(900px,94vw);padding:28px;border:1px solid rgba(255,255,255,.08);border-radius:24px;background:var(--card);box-shadow:var(--shadow);backdrop-filter:blur(12px)}\nh1{margin:0 0 10px;font-size:clamp(30px,5vw,56px);line-height:.96;letter-spacing:-.05em}\np{margin:0;color:#b3becc;line-height:1.7}\nbutton{appearance:none;border:1px solid rgba(255,255,255,.14);background:#111721;color:#fff;padding:13px 18px;border-radius:999px;font-weight:800;letter-spacing:.08em;cursor:pointer;transition:transform .18s ease,border-color .18s ease,background .18s ease}\nbutton:hover{transform:translateY(-1px);border-color:rgba(255,255,255,.26)}\nbutton.primary{background:linear-gradient(135deg,#d5142d,#ff4057);border-color:#ff5064;box-shadow:0 10px 28px rgba(255,39,64,.26)}\n.layer{position:fixed;inset:0;z-index:2147481000;display:grid;place-items:center;overflow:hidden;isolation:isolate;background:\n  radial-gradient(circle at 50% 28%, rgba(27,37,63,.95) 0, rgba(8,10,15,.96) 52%, #020305 100%);\n}\n.layer::before{content:\"\";position:absolute;inset:-14%;opacity:.11;background-image:linear-gradient(var(--line) 1px,transparent 1px),linear-gradient(90deg,var(--line) 1px,transparent 1px);background-size:42px 42px;transform:perspective(920px) rotateX(68deg) translateY(32%);mask-image:linear-gradient(to bottom,transparent,#000 22%,#000 74%,transparent)}\n.hud{position:absolute;left:max(18px,env(safe-area-inset-left));right:max(18px,env(safe-area-inset-right));top:max(16px,env(safe-area-inset-top));display:flex;justify-content:space-between;align-items:flex-start;z-index:22;pointer-events:none;gap:16px}\n.meta{display:flex;flex-direction:column;gap:7px}\n.brand{display:flex;align-items:center;gap:10px;font-size:11px;letter-spacing:.18em;text-transform:uppercase;color:#dde5f0}\n.brand::before{content:\"\";width:30px;height:3px;background:var(--accent);box-shadow:0 0 18px rgba(255,39,64,.8)}\n.status{font:700 12px/1.4 ui-monospace,SFMono-Regular,Menlo,Consolas,monospace;letter-spacing:.12em;text-transform:uppercase;color:var(--muted)}\n.status b{display:block;margin-top:4px;font-size:14px;color:#fff;letter-spacing:.18em}\n.actions{display:flex;gap:8px;pointer-events:auto}\n.actions button{padding:10px 13px;font-size:10px;background:#070a0fc9}\n.stage{position:relative;width:min(90vw,1240px);height:min(78vh,760px);display:grid;place-items:center;perspective:1300px}\n.stage > svg{width:100%;height:100%;overflow:visible;filter:drop-shadow(0 22px 24px rgba(0,0,0,.58))}\n.ring{position:absolute;width:min(72vw,860px);aspect-ratio:1;border-radius:50%;pointer-events:none;opacity:0;left:50%;top:50%;transform:translate(-50%,-50%) scale(.3);border:1px solid rgba(255,255,255,.28);box-shadow:0 0 90px rgba(255,39,64,.30), inset 0 0 90px rgba(158,255,177,.16)}\n.ring::before,.ring::after{content:\"\";position:absolute;inset:11%;border-radius:50%;border:1px dashed rgba(255,39,64,.25)}\n.ring::after{inset:24%;border-style:solid;border-color:rgba(255,255,255,.08)}\n.scan{position:absolute;left:8%;right:8%;top:14%;height:2px;opacity:0;background:linear-gradient(90deg,transparent,rgba(255,255,255,.92),var(--accent),rgba(255,255,255,.92),transparent);box-shadow:0 0 16px rgba(255,39,64,.55);pointer-events:none}\n.flash{position:absolute;inset:0;background:#fff;opacity:0;mix-blend-mode:screen;pointer-events:none}\n.corePulse{position:absolute;left:50%;top:50%;translate:-50% -50%;width:min(18vw,220px);aspect-ratio:1;border-radius:50%;opacity:0;background:radial-gradient(circle, rgba(255,255,255,.96) 0 9%, rgba(255,39,64,.92) 12%, rgba(255,39,64,.25) 32%, rgba(255,39,64,.05) 60%, transparent 74%);box-shadow:0 0 48px 18px rgba(255,39,64,.18)}\n.spark{position:absolute;left:50%;top:50%;width:4px;height:150px;translate:-50% -100%;opacity:0;transform-origin:50% 100%;background:linear-gradient(transparent, rgba(255,255,255,.95), var(--accent), transparent);pointer-events:none}\n.caps{position:absolute;left:50%;bottom:clamp(56px,8vh,96px);transform:translateX(-50%);width:min(92vw,760px);text-align:center;z-index:14;pointer-events:none}\n.caps>div{position:absolute;left:0;right:0;opacity:0;transform:translateY(8px)}\n.caps b{display:block;font-size:clamp(19px,2.35vw,32px);letter-spacing:.24em;text-indent:.24em}\n.caps small{display:block;margin-top:6px;color:#9aa6b6;font-size:9px;letter-spacing:.22em;text-transform:uppercase}\n.reveal{position:absolute;left:50%;top:50%;transform:translate(-50%,-50%);z-index:18;text-align:center;opacity:0;pointer-events:none}\n.reveal small{display:block;color:#9aa5b0;letter-spacing:.28em;font-size:10px}\n.reveal strong{display:block;font-size:clamp(52px,8vw,120px);line-height:.82;letter-spacing:-.06em;margin-top:10px}\n.reveal em{font-style:normal;color:var(--accent)}\n.progress{position:absolute;left:22px;right:22px;bottom:max(18px,env(safe-area-inset-bottom));height:2px;background:#ffffff18;overflow:hidden;z-index:20}\n.progress i{display:block;height:100%;background:linear-gradient(90deg,#fff,var(--accent),var(--accent2));transform-origin:left;transform:scaleX(0)}\n.s1,.s2full,.s2left,.s3full,.s3right,.s4full,.frag,.maskfrag,.pawfrag{opacity:0}\n.s1,.s2full,.s3full,.s4full,.frag,.maskfrag,.pawfrag{transform-origin:800px 450px;transform-box:view-box}\n.s2left,.s3right{transform-box:view-box}\n.s4full{filter:drop-shadow(0 0 18px rgba(255,255,255,.10))}\n.frag.center{transform-origin:800px 420px}\n.frag.upper.mech-left,.frag.mid.mech-left,.frag.lower.mech-left{transform-origin:820px 448px}\n.frag.upper.mech-right,.frag.mid.mech-right,.frag.lower.mech-right{transform-origin:780px 448px}\n.maskfrag{transform-origin:800px 430px}\n.pawfrag{transform-origin:800px 570px}\n.run .s1{animation:s1In .44s ease .04s both, s1Out .18s linear 1.16s forwards}\n.run .s2left{animation:leftLatchIn .84s var(--ease-mech) .64s both, leftOut .10s linear 1.42s forwards}\n.run .s2full{animation:softFadeIn .14s linear 1.18s both, settlePress .24s var(--ease-mech-soft) 1.20s both, softFadeOut .16s linear 2.22s forwards}\n.run .s3right{animation:rightLatchIn .86s var(--ease-mech) 1.42s both, rightOut .10s linear 2.22s forwards}\n.run .s3full{animation:softFadeIn .14s linear 2.10s both, lockPulse .20s ease 2.18s both, revolveTorque 1.18s var(--ease-turn) 2.62s both, preFade .24s ease 3.72s forwards}\n.run .frag.upper{animation:deployUpperHinge .72s var(--ease-mech-soft) var(--d) both, fragFade .18s linear 5.84s forwards}\n.run .frag.mid{animation:deployMidHinge .68s var(--ease-mech-soft) var(--d) both, fragFade .18s linear 5.84s forwards}\n.run .frag.lower{animation:deployLowerHinge .66s var(--ease-mech-soft) var(--d) both, fragFade .18s linear 5.84s forwards}\n.run .pawfrag{animation:pawSwingDown .56s var(--ease-mech) 4.48s both, fragFade .16s linear 5.84s forwards}\n.run .maskfrag{animation:maskLockForward .74s var(--ease-mech) 4.88s both, fragFade .16s linear 5.88s forwards}\n.run .s4full{animation:finalGhost .28s ease 5.20s both, finalSolid .34s ease 5.68s both}\n.run .flash{animation:flash .30s linear 5.28s both}\n.run .ring{animation:ring .88s cubic-bezier(.12,.82,.20,1) 5.20s both}\n.run .scan{animation:scan .86s linear .08s both, scan .66s linear 5.12s both}\n.run .corePulse{animation:coreBoot .34s ease 1.08s both, coreBoot .36s ease 1.96s both, coreBoot .48s ease 2.58s both, coreBurst .64s ease 5.18s both}\n.run .spark{animation:spark .52s ease 5.24s both}\n.run .caps [data-c=\"entry\"]{animation:cap .56s ease .08s both}\n.run .caps [data-c=\"white\"]{animation:cap .74s ease .64s both}\n.run .caps [data-c=\"red\"]{animation:cap .74s ease 1.42s both}\n.run .caps [data-c=\"lock\"]{animation:cap .54s ease 2.12s both}\n.run .caps [data-c=\"rev\"]{animation:cap 1.00s ease 2.64s both}\n.run .caps [data-c=\"deploy\"]{animation:cap 1.72s ease 3.88s both}\n.run .caps [data-c=\"final\"]{animation:cap 1.38s ease 5.32s both}\n.run .reveal{animation:reveal 1.16s cubic-bezier(.16,.84,.20,1) 5.72s both}\n.run .progress i{animation:progress 7.10s linear both}\n@keyframes s1In{from{opacity:0;transform:translateY(12px) scale(.97);filter:blur(6px)}to{opacity:1;transform:none;filter:none}}\n@keyframes s1Out{to{opacity:0}}\n@keyframes leftLatchIn{0%{opacity:0;transform:translate(-520px,18px) rotate(-6deg) scale(.99);filter:blur(8px)}60%{opacity:1;transform:translate(18px,-1px) rotate(.6deg) scale(1.006);filter:none}78%{transform:translate(-8px,0) rotate(-.35deg) scale(1.002)}100%{opacity:1;transform:none}}\n@keyframes rightLatchIn{0%{opacity:0;transform:translate(520px,-10px) rotate(6deg) scale(.99);filter:blur(8px)}60%{opacity:1;transform:translate(-18px,1px) rotate(-.6deg) scale(1.006);filter:none}78%{transform:translate(8px,0) rotate(.35deg) scale(1.002)}100%{opacity:1;transform:none}}\n@keyframes leftOut{to{opacity:0}}\n@keyframes rightOut{to{opacity:0}}\n@keyframes softFadeIn{from{opacity:0}to{opacity:1}}\n@keyframes softFadeOut{to{opacity:0}}\n@keyframes settlePress{0%{transform:none}40%{transform:translateX(6px) scale(1.004)}100%{transform:none}}\n@keyframes lockPulse{0%{transform:none;filter:none}40%{transform:scale(1.01);filter:brightness(1.07)}100%{transform:none;filter:none}}\n@keyframes revolveTorque{0%{opacity:1;transform:rotate(0deg) scale(1)}10%{transform:translateY(-2px) rotate(0deg) scale(1.005)}22%{transform:translateY(-1px) rotate(20deg) scale(1.003)}64%{transform:rotate(188deg) scale(.992)}84%{transform:rotate(177deg) scale(.996)}100%{opacity:1;transform:rotate(180deg) scale(.995)}}\n@keyframes preFade{to{opacity:0}}\n@keyframes deployUpperHinge{0%{opacity:0;transform:translate(var(--tx),var(--ty)) rotate(var(--r)) scale(.54);filter:brightness(1.12)}55%{opacity:1;transform:translate(calc(var(--tx) * -.12),-6px) rotate(calc(var(--r) * -.18)) scale(1.018);filter:brightness(1.03)}78%{transform:translate(calc(var(--tx) * .03),2px) rotate(calc(var(--r) * .05)) scale(.998)}100%{opacity:1;transform:none;filter:none}}\n@keyframes deployMidHinge{0%{opacity:0;transform:translate(var(--tx),var(--ty)) rotate(var(--r)) scale(.56);filter:brightness(1.10)}56%{opacity:1;transform:translate(calc(var(--tx) * -.10),-2px) rotate(calc(var(--r) * -.16)) scale(1.016)}80%{transform:translate(calc(var(--tx) * .03),1px) rotate(calc(var(--r) * .05)) scale(.998)}100%{opacity:1;transform:none;filter:none}}\n@keyframes deployLowerHinge{0%{opacity:0;transform:translate(var(--tx),var(--ty)) rotate(var(--r)) scale(.58);filter:brightness(1.08)}58%{opacity:1;transform:translate(calc(var(--tx) * -.08),4px) rotate(calc(var(--r) * -.18)) scale(1.014)}82%{transform:translate(calc(var(--tx) * .03),-1px) rotate(calc(var(--r) * .05)) scale(.998)}100%{opacity:1;transform:none;filter:none}}\n@keyframes pawSwingDown{0%{opacity:0;transform:translateY(-132px) rotate(88deg) scale(.48);filter:brightness(1.12)}58%{opacity:1;transform:translateY(8px) rotate(-5deg) scale(1.02)}80%{transform:translateY(-2px) rotate(2deg) scale(.998)}100%{opacity:1;transform:none;filter:none}}\n@keyframes maskLockForward{0%{opacity:0;transform:translateY(74px) rotateY(180deg) scale(.34);filter:brightness(1.16)}50%{opacity:1;transform:translateY(-5px) rotateY(20deg) scale(1.022)}76%{transform:translateY(2px) rotateY(-5deg) scale(.998)}100%{opacity:1;transform:none;filter:none}}\n@keyframes finalGhost{0%{opacity:0;filter:brightness(1.22)}100%{opacity:.22;filter:brightness(1.05)}}\n@keyframes finalSolid{0%{opacity:.22;filter:brightness(1.05)}100%{opacity:1;filter:none}}\n@keyframes fragFade{to{opacity:0}}\n@keyframes flash{0%,100%{opacity:0}18%{opacity:.82}42%{opacity:.12}}\n@keyframes ring{0%{opacity:.95;transform:translate(-50%,-50%) scale(.22)}100%{opacity:0;transform:translate(-50%,-50%) scale(1.12)}}\n@keyframes scan{0%{opacity:0;top:14%}14%{opacity:.92}86%{opacity:.38;top:86%}100%{opacity:0;top:92%}}\n@keyframes coreBoot{0%{opacity:0;transform:scale(.18)}34%{opacity:.95;transform:scale(.88)}100%{opacity:0;transform:scale(1.28)}}\n@keyframes coreBurst{0%{opacity:0;transform:scale(.26)}24%{opacity:1;transform:scale(.94)}100%{opacity:0;transform:scale(1.58)}}\n@keyframes spark{0%{opacity:0;transform:scaleY(.2)}24%{opacity:.95;transform:scaleY(1)}100%{opacity:0;transform:scaleY(1.38)}}\n@keyframes cap{0%{opacity:0;transform:translateY(8px)}18%,72%{opacity:1;transform:none}100%{opacity:0;transform:translateY(-8px)}}\n@keyframes reveal{0%{opacity:0;transform:translate(-50%,-46%) scale(.95);filter:blur(7px)}24%,76%{opacity:1;transform:translate(-50%,-50%);filter:none}100%{opacity:0;transform:translate(-50%,-54%) scale(1.02)}}\n@keyframes progress{to{transform:scaleX(1)}}\n@media(max-width:760px){\n  .stage{width:100vw;height:60vh;transform:scale(.80)}\n  .brand span{display:none}\n  .caps{bottom:78px}\n  .actions button[data-sfx]{display:none}\n  .status{font-size:11px}\n  .card{padding:22px}\n}\n.rgx-host{display:block}.rgx-card{width:min(900px,100%);padding:24px;border:1px solid rgba(255,255,255,.08);border-radius:24px;background:var(--card);box-shadow:var(--shadow);backdrop-filter:blur(12px)}.rgx-row{display:flex;gap:10px;flex-wrap:wrap;margin-top:18px}.rgx-kicker{font-size:12px;letter-spacing:.22em;text-transform:uppercase;color:#9aa6b6;margin-bottom:10px}.rgx-title{margin:0 0 8px;font-size:clamp(28px,4vw,46px);line-height:.96;letter-spacing:-.05em}.rgx-copy{margin:0;color:#b3becc;line-height:1.7}";
